+  long rssi = 0;
+  size_t ssid_len;
+
+  if (line == NULL || ap == NULL)
+    {
+      return false;
+    }
+
+  ssid_start = strstr(line, "ssid=\"");
+  if (ssid_start == NULL)
+    {
+      return false;
+    }
+
+  ssid_start += strlen("ssid=\"");
+  ssid_end = strchr(ssid_start, '"');
