static void ui_demo_wifi_read_fd(int fd, char *output, size_t output_len)
{
  size_t used = 0;

  if (output == NULL || output_len == 0)
    {
      char scratch[96];

      while (read(fd, scratch, sizeof(scratch)) > 0)
        {
        }

      return;
    }

  output[0] = '\0';
  while (used + 1 < output_len)
    {
      ssize_t nread = read(fd, output + used, output_len - used - 1);

      if (nread <= 0)
        {
          break;
        }

      used += (size_t)nread;
      output[used] = '\0';
    }

  if (used + 1 >= output_len)
    {
      char scratch[96];

      while (read(fd, scratch, sizeof(scratch)) > 0)
        {
        }
    }
}

